INSERT INTO public.movies (id, title, year, genre, picture, status, tmdb_id, type, id_user, delete_request_status, delete_request_by, delete_request_at, edit_status, pending_title, pending_year, pending_genre, edit_requested_at, synopsis, validated_at, slug, hidden, "createdAt", "updatedAt") VALUES (30, 'Film de test', 2024, 'comédie', NULL, 'pending', NULL, 'film', 124, 'none', NULL, NULL, 'none', NULL, NULL, NULL, NULL, 'Description du film', NULL, 'film-de-test', false, '2026-03-31 11:14:15.998261+02', '2026-03-31 11:14:15.998261+02');
INSERT INTO public.movies (id, title, year, genre, picture, status, tmdb_id, type, id_user, delete_request_status, delete_request_by, delete_request_at, edit_status, pending_title, pending_year, pending_genre, edit_requested_at, synopsis, validated_at, slug, hidden, "createdAt", "updatedAt") VALUES (2, 'American pie', 1999, 'comédie', '/images/movies/originals/american-pie.jpg', 'approved', 2105, 'film', NULL, 'none', NULL, NULL, 'none', NULL, NULL, NULL, NULL, 'L''année scolaire se termine au lycée de Great Falls. Désespéré depuis que ses parents l''ont surpris dans une situation plus que gênante devant un film X, Jim, élève de terminale, scelle un pacte avec sa bande de copains : finis les plaisirs solitaires, ils seront tous des hommes avant d''entrer à la fac. Il leur reste donc trois semaines pour utiliser toutes les techniques possibles de séduction.', NULL, 'american-pie', false, '2026-03-31 08:46:56.774694+02', '2026-03-31 08:46:56.774694+02');
INSERT INTO public.movies (id, title, year, genre, picture, status, tmdb_id, type, id_user, delete_request_status, delete_request_by, delete_request_at, edit_status, pending_title, pending_year, pending_genre, edit_requested_at, synopsis, validated_at, slug, hidden, "createdAt", "updatedAt") VALUES (3, 'Bienvenue chez les Ch''tis', 2008, 'comédie', '/images/movies/originals/bienvenue-chez-les-ch-tis.jpg', 'approved', 8265, 'film', NULL, 'none', NULL, NULL, 'none', NULL, NULL, NULL, NULL, 'Un directeur de la Poste en Provence est, à son détriment, muté à Bergues, petite ville du Nord. Sa famille refusant de l''accompagner, Philippe ira seul. A sa grande surprise, il découvre un endroit charmant, une équipe chaleureuse et des gens accueillants. Il se lie d''amitié avec Antoine, le facteur et le carillonneur du village, à la mère possessive et aux amours contrariées.', NULL, 'bienvenue-chez-les-chtis', false, '2026-03-31 08:46:56.774694+02', '2026-03-31 08:46:56.774694+02');
INSERT INTO public.movies (id, title, year, genre, picture, status, tmdb_id, type, id_user, delete_request_status, delete_request_by, delete_request_at, edit_status, pending_title, pending_year, pending_genre, edit_requested_at, synopsis, validated_at, slug, hidden, "createdAt", "updatedAt") VALUES (33, 'Harry Potter et le Prisonnier d''Azkaban', 2004, 'fantastique', '/images/movies/originals/harry-potter-et-le-prisonnier-d-azkaban.jpg', 'approved', 673, 'film', 3, 'none', NULL, NULL, 'none', NULL, NULL, NULL, NULL, 'Sirius Black, un dangereux sorcier criminel, s’échappe de la sombre prison d’Azkaban avec un seul et unique but : retrouver Harry Potter, en troisième année à l’école de Poudlard. Selon la légende, Black aurait jadis livré les parents du jeune sorcier à leur assassin, Lord Voldemort, et serait maintenant déterminé à tuer Harry…', NULL, 'harry-potter-et-le-prisonnier-dazkaban', false, '2026-04-03 16:09:07.209572+02', '2026-04-03 16:09:07.209572+02');
INSERT INTO public.movies (id, title, year, genre, picture, status, tmdb_id, type, id_user, delete_request_status, delete_request_by, delete_request_at, edit_status, pending_title, pending_year, pending_genre, edit_requested_at, synopsis, validated_at, slug, hidden, "createdAt", "updatedAt") VALUES (34, 'Harry Potter à l''école des sorciers', 2001, 'aventure', '/images/movies/originals/harry-potter-a-l-ecole-des-sorciers.jpg', 'approved', 671, 'film', 122, 'none', NULL, NULL, 'none', NULL, NULL, NULL, NULL, 'Orphelin, le jeune Harry Potter peut enfin quitter ses tyranniques oncle et tante Dursley lorsqu''un curieux messager lui révèle qu''il est un sorcier. À 11 ans, Harry va enfin pouvoir intégrer la légendaire école de sorcellerie de Poudlard, y trouver une famille digne de ce nom et des amis, développer ses dons, et préparer son glorieux avenir.', '2026-04-15 09:30:50.203', 'harry-potter-a-lecole-des-sorciers', false, '2026-04-15 11:30:50.220221+02', '2026-04-15 11:30:50.220221+02');
INSERT INTO public.movies (id, title, year, genre, picture, status, tmdb_id, type, id_user, delete_request_status, delete_request_by, delete_request_at, edit_status, pending_title, pending_year, pending_genre, edit_requested_at, synopsis, validated_at, slug, hidden, "createdAt", "updatedAt") VALUES (16, 'Ratatouille', 2007, 'animation', '/images/movies/originals/ratatouille.jpg', 'approved', 2062, 'film', 122, 'none', NULL, NULL, 'none', NULL, NULL, NULL, NULL, 'Rémy est un jeune rat qui rêve de devenir un grand chef français. Ni l''opposition de sa famille, ni le fait d''être un rongeur dans une profession qui les déteste ne le démotivent. Rémy est prêt à tout pour vivre sa passion de la cuisine… et le fait d''habiter dans les égouts du restaurant ultra coté de la star des fourneaux, Auguste Gusteau, va lui en donner l''occasion ! Malgré le danger et les pièges, la tentation est grande de s''aventurer dans cet univers interdit. Écartelé entre son rêve et sa condition, Rémy va découvrir le vrai sens de l''aventure, de l''amitié, de la famille… et comprendre qu''il doit trouver le courage d''être ce qu''il est : un rat qui veut être un grand chef…', '2026-03-31 11:58:56.55726', 'ratatouille', false, '2026-03-31 08:46:56.774694+02', '2026-03-31 08:46:56.774694+02');
INSERT INTO public.movies (id, title, year, genre, picture, status, tmdb_id, type, id_user, delete_request_status, delete_request_by, delete_request_at, edit_status, pending_title, pending_year, pending_genre, edit_requested_at, synopsis, validated_at, slug, hidden, "createdAt", "updatedAt") VALUES (31, 'Breaking Bad', 2008, 'drame', '/images/movies/originals/breaking-bad.jpg', 'approved', 1396, 'film', 3, 'none', NULL, NULL, 'none', NULL, NULL, NULL, NULL, 'Un professeur de chimie atteint d''un cancer s''associe à un ancien élève pour fabriquer et vendre de la méthamphétamine afin d''assurer l''avenir financier de sa famille.', '2026-03-31 11:59:38.508', 'breaking-bad', false, '2026-03-31 13:59:38.517508+02', '2026-03-31 13:59:38.517508+02');
INSERT INTO public.movies (id, title, year, genre, picture, status, tmdb_id, type, id_user, delete_request_status, delete_request_by, delete_request_at, edit_status, pending_title, pending_year, pending_genre, edit_requested_at, synopsis, validated_at, slug, hidden, "createdAt", "updatedAt") VALUES (5, 'Indiana Jones et les Aventuriers de l''Arche perdue', 1981, 'aventure', '/images/movies/originals/indiana-jones-et-les-aventuriers-de-l-arche-perdue.jpg', 'approved', 85, 'film', 3, 'none', NULL, NULL, 'none', NULL, NULL, NULL, NULL, 'Professeur d''archéologie, Indiana Jones parcourt le monde à la recherche de trésors. Son rival, le Français René Belloq, travaille pour les nazis qui rêvent de retrouver l''Arche d''alliance contenant les Tables de la Loi. Or, feu le professeur Ravenwood, père de Marion, l''ex-petite amie d''Indiana Jones, détenait une médaille permettant de localiser l''arche. Jones part sur les traces de Marion au Népal.', NULL, 'indiana-jones-et-les-aventuriers-de-larche-perdue', false, '2026-03-31 08:46:56.774694+02', '2026-03-31 08:46:56.774694+02');
INSERT INTO public.movies (id, title, year, genre, picture, status, tmdb_id, type, id_user, delete_request_status, delete_request_by, delete_request_at, edit_status, pending_title, pending_year, pending_genre, edit_requested_at, synopsis, validated_at, slug, hidden, "createdAt", "updatedAt") VALUES (4, 'Le silence des agneaux', 1991, 'thriller', '/images/movies/originals/le-silence-des-agneaux.jpg', 'approved', 274, 'film', NULL, 'none', NULL, NULL, 'none', NULL, NULL, NULL, NULL, 'Un psychopathe connu sous le nom de `Buffalo Bill'' sème la terreur dans le `Middle West'' en kidnappant et en assassinant de jeunes femmes. Clarice Starling, une jeune agent du FBI, est chargée d''interroger l''ex-psychiatre Hannibal Lecter. Psychopathe redoutablement intelligent et porté sur le cannibalisme, Lecter est capable de lui fournir des informations. Entre eux s''établit un lien de fascination et de répulsion.', NULL, 'le-silence-des-agneaux', false, '2026-03-31 08:46:56.774694+02', '2026-03-31 08:46:56.774694+02');


