INSERT INTO public.recipes (id, name, description, picture, category, quote, ingredients, preparation, "time", difficulty, status, id_movie, id_user, edit_status, pending_name, pending_description, pending_picture, pending_category, pending_ingredients, pending_preparation, pending_time, pending_difficulty, edit_requested_at, servings, validated_at, slug, delete_request_status, delete_request_at, "createdAt", "updatedAt") VALUES (21, 'La Ratatouille de Remy', 'Dans Ratatouille, c''est ce plat que le petit Remy prépare pour le redoutable critique culinaire Anton Ego..une bouchée qui le replonge instantanément dans son enfance. La version confit byaldi, inspirée du chef Thomas Keller, est celle que Pixar a immortalisée à l''écran : des légumes finement tranchés, disposés en rosace parfaite sur une sauce piperade maison. La cuisine n''est pas réservée à tout le monde… mais tout le monde peut apprendre.', '/images/recipes/recipe-recipes-ratatouille-1-1774949314454-820365142-processed.jpg', 'plat', 0, '["2 courgettes","1 aubergine","3 tomates rondes","1 poivron rouge","1 poivron jaune","1 oignon","3 gousses d’ail","400 g de tomates concassées en boîte","4 cuillères à soupe d’huile d’olive","4 branches de thym frais","2 branches de romarin frais","10 feuilles de basilic frais","1 cuillère à café de sucre"]', '["<strong>Préparer la sauce piperade</strong> : Émincer 1 oignon et 3 gousses d’ail. Couper 1 poivron rouge et 1 poivron jaune en petits dés. Faire revenir le tout dans une casserole avec 4 cuillères à soupe d’huile d’olive à feu moyen pendant 10 minutes. Ajouter 400 g de tomates concassées en boîte, 1 cuillère à café de sucre, 4 branches de thym frais et 2 branches de romarin frais. Saler, poivrer et laisser mijoter 15 minutes à feu doux jusqu’à obtenir une sauce bien réduite.","<strong>Trancher les légumes – la précision de Rémy</strong> : Laver soigneusement 2 courgettes, 1 aubergine et 3 tomates rondes. Les trancher en rondelles très fines et régulières d’environ 3 mm — c’est le secret d’une belle présentation. Un couteau bien aiguisé et pas de précipitation.","<strong>Monter la ratatouille confit</strong> : Préchauffer le four à 160°C. Étaler la sauce piperade en couche uniforme au fond d’un plat à gratin rond. Disposer les rondelles de légumes en les alternant et en les chevauchant légèrement en cercles concentriques : courgette, tomate, aubergine, courgette, tomate, aubergine… jusqu’à remplir tout le plat.","<strong>Assaisonner et couvrir</strong> : Arroser d’un filet de 4 cuillères à soupe d’huile d’olive, parsemer de 4 branches de thym frais et 2 branches de romarin frais. Assaisonner à votre goût. Couvrir le plat d’une feuille de papier cuisson découpée à la taille du plat.","<strong>Cuisson lente au four</strong> : Enfourner à 160°C pendant 45 minutes. Retirer ensuite le papier cuisson et prolonger la cuisson de 15 minutes pour faire légèrement caraméliser le dessus.","<strong>Dresser comme un grand chef</strong> : Laisser reposer 5 minutes hors du four. Dresser harmonieusement dans les assiettes en superposant délicatement les rondelles. Parsemer de 10 feuilles de basilic frais ciselé et d’un dernier filet d’huile d’olive. Servir chaud ou tiède."]', 60, 'Moyenne', 'approved', 16, 122, 'none', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 4, '2026-03-31 09:29:49.492', 'la-ratatouille-de-remy', 'none', NULL, '2026-03-31 11:28:34.734845+02', '2026-03-31 11:28:34.734845+02');
INSERT INTO public.recipes (id, name, description, picture, category, quote, ingredients, preparation, "time", difficulty, status, id_movie, id_user, edit_status, pending_name, pending_description, pending_picture, pending_category, pending_ingredients, pending_preparation, pending_time, pending_difficulty, edit_requested_at, servings, validated_at, slug, delete_request_status, delete_request_at, "createdAt", "updatedAt") VALUES (6, 'Le Bol du Temple Perdu', 'Après avoir exploré des temples et traversé la jungle, Indiana Jones fait une pause sur un campement improvisé. Il savoure un bol rustique de riz, légumes et viande avant de reprendre son aventure pleine de dangers et de mystères.', '/images/recipes/recette-indiana-jones-bol-expedition-v1-1764166522021-433994479.png', 'plat', 0, '["200 g de riz parfumé (basmati ou jasmin)","250 g de morceaux de poulet ou bœuf grillé","1 poivron rouge, coupé en dés","1 carotte, coupée en fines rondelles","50 g de maïs en grains","1 oignon moyen, émincé","2 gousses d''ail, hachées","1 c. à soupe d''huile de coco ou d''olive","100 ml de bouillon de volaille ou légumes","1 c. à café de curry doux ou paprika fumé","1 c. à soupe de sauce soja","Sel et poivre au goût","Quelques feuilles de coriandre pour la déco","Accessoires pour créer l''ambiance Indiana Jones :","Carnet en cuir, boussole, lanterne, herbes sauvages, planche en bois ou toile de jute"]', '["Préparer le riz : cuire selon les indications du paquet. Égoutter et réserver au chaud.","Cuisson des légumes : faire revenir oignon et ail dans l''huile jusqu''à transparence. Ajouter carotte, poivron, maïs, cuire 5–7 min.","Cuisson de la viande : griller ou poêler les morceaux, ajouter curry/paprika et sauce soja.","Assemblage : riz en base, légumes et viande par-dessus, verser un filet de bouillon pour humidifier légèrement.","Finition / mise en scène : décorer de coriandre, disposer accessoires autour du bol pour l''ambiance expédition. Servir chaud, angle légèrement plongeant pour le visuel Indiana Jones."]', 25, 'Moyenne', 'approved', 5, 3, 'rejected', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'le-bol-du-temple-perdu', 'none', NULL, '2026-03-31 08:46:56.774694+02', '2026-03-31 08:46:56.774694+02');
INSERT INTO public.recipes (id, name, description, picture, category, quote, ingredients, preparation, "time", difficulty, status, id_movie, id_user, edit_status, pending_name, pending_description, pending_picture, pending_category, pending_ingredients, pending_preparation, pending_time, pending_difficulty, edit_requested_at, servings, validated_at, slug, delete_request_status, delete_request_at, "createdAt", "updatedAt") VALUES (24, 'la tarte à la mélasse', 'Cette tarte apparaît lors du premier grand banquet à Poudlard dans le film Harry Potter à l''école des sorciers. Elle fait partie des nombreux desserts servis dans la Grande Salle et deviendra ensuite connue comme le dessert préféré de Harry Potter. Elle symbolise la découverte d’un foyer chaleureux et l’abondance du monde magique après une enfance marquée par la privation.', '/images/recipes/recipe-tarte-melasse-harry-potter-ecole-sorciers-principale-1776247390928-933391108-processed.jpg', 'Dessert', 0, '["<h3 class=\"rd-ing-group-title\">Pour la pâte sablée</h3>","250 g de farine","125 g de beurre froid","80 g de sucre glace","1 œuf","1 pincée de sel","<h3 class=\"rd-ing-group-title\">Pour la garniture</h3>","300 g de golden syrup ou sirop de sucre épais","150 g de mie de pain ou chapelure fine","1 citron (zeste et jus)","1 œuf","30 g de beurre fondu"]', '["Préparer la pâte sablée en mélangeant la farine, le sucre glace et le sel. Ajouter le beurre froid coupé en petits morceaux puis sabler la pâte du bout des doigts jusqu''à obtenir une texture sableuse. Incorporer l''œuf et former une boule homogène. Filmer la pâte et la placer au réfrigérateur pendant environ 30 minutes.","<strong>Préchauffer le four à 180 degrés.</strong> Étaler la pâte et la déposer dans un moule à tarte d''environ 24 centimètres de diamètre. Piquer le fond avec une fourchette puis cuire à blanc pendant environ 10 minutes.","<strong>Préparer la garniture</strong> en mélangeant le golden syrup, la mie de pain, le zeste et le jus de citron. Ajouter l''œuf et le beurre fondu puis mélanger jusqu''à obtenir une texture épaisse et légèrement granuleuse.","<strong>Verser la garniture</strong> sur le fond de tarte précuit puis enfourner pendant 20 à 25 minutes jusqu''à ce que la surface soit dorée. Laisser tiédir avant de servir pour obtenir une texture fondante et caramélisée.","Ambiance et goût attendu :<br><ul><li>Texture fondante et légèrement croustillante</li><li>Goût très sucré, citronné et caramélisé</li><li>Dessert réconfortant typique des repas festifs de Poudlard 🍮</li></ul>"]', 50, 'Facile', 'approved', 34, 122, 'none', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 6, '2026-04-15 10:03:39.779', 'la-tarte-a-la-melasse', 'none', NULL, '2026-04-15 12:03:11.022162+02', '2026-04-15 12:03:11.022162+02');
INSERT INTO public.recipes (id, name, description, picture, category, quote, ingredients, preparation, "time", difficulty, status, id_movie, id_user, edit_status, pending_name, pending_description, pending_picture, pending_category, pending_ingredients, pending_preparation, pending_time, pending_difficulty, edit_requested_at, servings, validated_at, slug, delete_request_status, delete_request_at, "createdAt", "updatedAt") VALUES (22, 'Le Chili de Heisenberg', 'Dans Breaking Bad, Walter White est un homme méticuleux, obsédé par la pureté et la précision. Ce chili texan ultra-épicé incarne son double visage : en apparence un plat familial ordinaire, en réalité une bombe soigneusement dosée. Le chocolat noir, ingrédient secret, rappelle que derrière chaque recette anodine peut se cacher une complexité insoupçonnée. Je suis celui qui toque… et qui assaisonne.', '/images/recipes/recipe-breaking-bad-1-1774958378485-907110527-processed.jpg', 'plat', 0, '["500 g de bœuf haché","400 g de haricots rouges en boîte, égouttés","400 g de tomates concassées en boîte","1 oignon","4 gousses d’ail","2 c. à café de piment chipotle fumé","2 c. à café de cumin en poudre","1 c. à soupe de paprika fumé","1 c. à café de piment de Cayenne","1 poivron rouge","200 ml de bouillon de bœuf","20 g de chocolat noir (70 %)","2 c. à soupe d’huile d’olive"]', '["Préparer la base aromatique : Émincer finement l’oignon et l’ail. Couper le poivron rouge en petits dés. Dans une grande cocotte, faire chauffer l’huile d’olive à feu moyen et faire revenir l’oignon jusqu’à ce qu’il devienne translucide. Ajouter ensuite l’ail et le poivron et poursuivre la cuisson 2-3 minutes.","Faire dorer la viande : Ajouter le bœuf haché et le faire revenir en émiettant bien la viande. Assaisonner selon ton goût.","Ajouter les épices : Saupoudrer le piment chipotle, le cumin, le paprika et le piment de Cayenne. Bien mélanger et laisser torréfier les épices 1 à 2 minutes à feu vif. Cette étape développe toutes les saveurs.","Incorporer les liquides et légumineuses : Ajouter les tomates concassées, les haricots rouges et le bouillon de bœuf. Bien mélanger, porter à ébullition, puis réduire le feu à doux.","Mijoter lentement : Laisser mijoter à découvert pendant 40 minutes en remuant de temps en temps, jusqu’à ce que le chili épaississe.","La touche finale : En fin de cuisson, incorporer le chocolat noir râpé et mélanger jusqu’à ce qu’il soit complètement fondu. Il apporte profondeur et légère amertume.","Servir : Servir bien chaud dans des bols. Accompagner de riz blanc ou de pain de maïs. Ajouter éventuellement une touche de crème fraîche ou de cheddar râpé pour adoucir le plat."]', 20, 'Moyenne', 'approved', 31, 3, 'none', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 4, '2026-03-31 12:02:52.331', 'le-chili-de-heisenberg', 'none', NULL, '2026-03-31 13:59:38.751141+02', '2026-03-31 13:59:38.751141+02');
INSERT INTO public.recipes (id, name, description, picture, category, quote, ingredients, preparation, "time", difficulty, status, id_movie, id_user, edit_status, pending_name, pending_description, pending_picture, pending_category, pending_ingredients, pending_preparation, pending_time, pending_difficulty, edit_requested_at, servings, validated_at, slug, delete_request_status, delete_request_at, "createdAt", "updatedAt") VALUES (4, 'carbonnade flamande', 'À l''minche chez Antoine, quand qu''Philippe y''est invité à goûter les spécialités du Nord. Ch''est là qu''on l''y sert l''fameuse carbonnade flamande.
Oups!!
Au repas chez Antoine, quand Philippe  est invité à découvrir les spécialités du Nord. C''est à ce moment qu''on lui sert la fameuse carbonnade flamande.', '/images/recipes/carbonnade_chtis-1764138416283-708167994.jpeg', 'plat', 0, '["<h3 class=\"rd-ing-group-title\">pour 6 personnes</h3>","1,5 kg de viande de boeuf à braiser (gîte, paleron, jumeau...)","6 oignons","20 g de beurre doux","3 cuillerées à soupe de farine","3 cuillerées à soupe de vinaigre de vin rouge","1 litre de bière brune","3 cuillerées à soupe de vergeoise brune (ou cassonade)","2 feuilles de laurier","4 branches de thym séché","3 clous de girofle","8 tranches (160g) de pain d''épices","5 cuillerées à soupe de moutarde","Sel, poivre"]', '["Découpez la viande en tranches épaisses. Epluchez les oignons et coupez-les en rondelles.","Dans une cocotte, faites dorer les tranches de viande dans le beurre fondu. (Faites-le en deux fois si la cocotte est petite). Assaisonnez. Ajoutez la farine et les oignons. Mélangez bien et laissez cuire 5 min tout en remuant, pour attendrir les oignons sans les colorer.","Ajoutez le vinaigre et laissez cuire 2 min. Puis ajoutez la bière, 50 cl d''eau, la vergeoise, le thym, le laurier, les clous de girofle et 5 tranches de pain d''épices tartinées de moutarde. Portez à ébullition, couvrez puis baissez le feu pour laisser mijoter 2h45.","Retirez le couvercle, augmentez le feu et faites cuire à découvert en remuant, jusqu''à ce que la sauce ait réduit de moitié.","Faites griller les tranches de pain d''épices restantes et coupez-les en cubes.","Servez la carbonade avec des petites pommes de terre vapeur et les cubes de pain d''épices grillés."]', 220, 'Facile', 'approved', 3, 3, 'none', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'carbonnade-flamande', 'none', NULL, '2026-03-31 08:46:56.774694+02', '2026-03-31 08:46:56.774694+02');
INSERT INTO public.recipes (id, name, description, picture, category, quote, ingredients, preparation, "time", difficulty, status, id_movie, id_user, edit_status, pending_name, pending_description, pending_picture, pending_category, pending_ingredients, pending_preparation, pending_time, pending_difficulty, edit_requested_at, servings, validated_at, slug, delete_request_status, delete_request_at, "createdAt", "updatedAt") VALUES (2, 'Apple pie', 'Dans le film American Pie, la scène où Jim se retrouve en tête à tête avec la tarte aux pommes se produit lorsqu''il est surpris par ses parents. Cette scène est considérée comme mythique et est l''une des plus célèbres du film. Elle a marqué la mémoire des spectateurs et est devenue un moment emblématique de la saga', '/images/recipes/applepie-1764137966385-745300976.jpg', 'dessert', 0, '["Farine 300g,","Beurre mou 190g,","Eau 5cl,","Bicarbonate de soude 1 demi cuillère à café,","Sel 1 pincée","Pomme Reinette 1 kg,","Cassonade 25 g,","Cannelle en poudre 5 g,","Citron(s) jaune(s) 1."]', '["Préparez la pâte. Coupez le beurre ramolli en dés. Dans un saladier, versez la farine et creusez-y un puits. Versez-y le beurre, le sel et le bicarbonate. Pétrissez grossièrement, puis incorporez progressivement l''eau. Pétrissez à nouveau jusqu''à former une boule. Couvrez le saladier et laissez reposer 30 min au frais.","Préchauffez le four th.6 (180°C). Épluchez et épépinez les pommes, puis coupez-les en morceaux. Arrosez-les du jus du citron jaune dans un saladier, ajoutez la cannelle et mélangez pour enrober les pommes.","Sortez la pâte et étalez-la sur un plan de travail fariné, assez pour y découper deux disques plus grands que votre moule. Placez le premier au fond du moule. Tapissez-le de morceaux de pommes. Recouvrez avec le second disque de pâte. Scellez les bords en pinçant avec les doigts, puis découpez des incisions en étoile sur le dessus, afin que la vapeur s''échappe.","Saupoudrez de cassonade et enfournez pour 55 min."]', 75, 'Facile', 'approved', 2, 3, 'none', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'apple-pie', 'none', NULL, '2026-03-31 08:46:56.774694+02', '2026-03-31 08:46:56.774694+02');
INSERT INTO public.recipes (id, name, description, picture, category, quote, ingredients, preparation, "time", difficulty, status, id_movie, id_user, edit_status, pending_name, pending_description, pending_picture, pending_category, pending_ingredients, pending_preparation, pending_time, pending_difficulty, edit_requested_at, servings, validated_at, slug, delete_request_status, delete_request_at, "createdAt", "updatedAt") VALUES (5, 'le foie et ses fèves au beurre', 'Dans le film Le Silence des Agneaux, lors d''un entretien en tête à tête avec l''agent Clarice Starling, le Docteur Hannibal Lecter, psychopathe cannibale, dans un thriller policier, et esthète culinaire s''il en est, mentionne ceci :

« J''ai été interrogé par un employé du recensement. J''ai dégusté son foie avec des fèves au beurre, et un excellent chianti »', '/images/recipes/recipe-recette-le-foie-et-ses-feves-au-beurre (1)-1771868748364-695886615.png', 'plat', 0, '["800 g de fèves fraîches.","Beurre","1 échalote","2 pincées de sucre","Vinaigre de vin","1/2 verre de vin rouge","1 verre de bouillon","2 c. à s. de ciboulette hachée","2 tranches de foie de veau surtout pas trop fines","Sel et poivre"]', '["Les fèves<br>Plongez-les 15-20 secondes dans de l''eau bouillante puis dans de l''eau froide. Egouttez et ôtez la peau entourant les fèves, mettez de côté. Epluchez et hachez l''échalote.","Le foie<br>Salez, poivrez les tranches de foie et, dans une poêle chauffée à feu moyen, couchez-les dans une ou deux noix de beurre moussant. Comptez 2-3 minutes de cuisson, retournez les tranches, laissez cuire  2-3 minutes puis conservez au chaud entre deux assiettes.","Le foie et les fèves<br>Dans le jus de cuisson des tranches de foie, ajoutez les échalotes, ajoutez un petit trait de vinaigre, laissez évaporer, versez le vin. Faites-le s''évaporer (ou presque) puis videz le bouillon. Faites bouillir et réduire de moitié. Ajoutez les fèves et le sucre, salez, poivrez et laissez mijoter 2 à 3 minutes puis ajoutez la ciboulette. Servez les tranches de foie nappées de cette superbe sauce.","Servez-vous un excellent Chianti pour dégustez et savourez ce foie accompagné de ses fèves."]', 60, 'Facile', 'approved', 4, 3, 'none', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'le-foie-et-ses-feves-au-beurre', 'none', NULL, '2026-03-31 08:46:56.774694+02', '2026-03-31 08:46:56.774694+02');
INSERT INTO public.recipes (id, name, description, picture, category, quote, ingredients, preparation, "time", difficulty, status, id_movie, id_user, edit_status, pending_name, pending_description, pending_picture, pending_category, pending_ingredients, pending_preparation, pending_time, pending_difficulty, edit_requested_at, servings, validated_at, slug, delete_request_status, delete_request_at, "createdAt", "updatedAt") VALUES (3, 'bièraubeurre', 'La Bièraubeurre, souvent confondue avec un soda par ceux qui n''ont jamais eu le privilège d''y goûter, est une boisson emblématique de l''univers d''Harry Potter. En dépit de sa popularité dans la cuisine des sorciers, elle trouve aussi sa place parmi les cocktails moldus inspirés par la magie. À la fois pétillante et envoûtante, cette boisson est souvent agrémentée de sirops pour rehausser son goût unique.', '/images/recipes/recipe-bieraubeurre-principal-1775226094940-232690939.jpg', 'Dessert', 0, '["Bière sans alcool 33 cls","1 cuillère à café de sucre roux","1 noisette de beurre","Crème  (chantilly, ou 20cl de creme liquide et 1 pincee de sucre)","Epices au choix  (cannelle, gingembre, clou de girofle en poudre)"]', '["Commencez par verser le sucre roux dans une casserole, puis ajoutez les 2 cuillères à soupe d''eau. Chauffez à feu moyen et patientez jusqu''à l''apparition de bulles dorées signalant que le mélange commence à caraméliser. Tout en remuant délicatement, incorporez le beurre dans ce doux mélange jusqu''à sa parfaite fusion. N''oubliez pas d''ajouter quelques gouttes de vinaigre de cidre, pour ajouter une subtile touche acidulée.","Versez progressivement la crème liquide tout en continuant à remuer jusqu''à obtenir une préparation homogène. Pour une note épicée, ajoutez une pincée de cannelle selon vos goûts et remuez bien.","Une fois votre concoction prête, laissez-la refroidir directement dans des verres à bière. À l''heure de la dégustation, versez un peu de bière dans le verre contenant votre préparation refroidie, et remuez avec grâce. Selon votre palais, vous pouvez choisir un panaché, une bière sans alcool ou même une bière classique. Pour couronner le tout, n''oubliez pas de garnir d''une onctueuse couche de crème chantilly.&quot;"]', 15, 'Facile', 'approved', 33, 3, 'none', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'bieraubeurre', 'none', NULL, '2026-03-31 08:46:56.774694+02', '2026-03-31 08:46:56.774694+02');


